const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const weekAgoISO = weekAgo.toISOString().split('T')[0];
const nowISO = now.toISOString().split('T')[0];

return [{
  json: {
    ...$json,
    weekStart: weekAgoISO,
    weekEnd: nowISO,
    period: `${weekAgoISO} to ${nowISO}`
  }
}];

// Extract data
const commits = $json.commits?.items || [];
const issues = $json.issues?.items || [];
const prs = $json.prs?.items || [];
const repo = $json.githubRepo || 'owner/repo';
const lang = $json.language || 'EN';
const period = $json.period || 'this week';

// Count stats
const totalCommits = commits.length;
const totalIssues = issues.length;
const totalPRs = prs.length;

// Top contributors
const contributors = [...new Set(commits.map(c => c.author?.login).filter(Boolean))];

// Format issue titles
const issueTitles = issues.slice(0,10).map(i => `  - #${i.number}: ${i.title}`).join('\n');
const prTitles = prs.slice(0,10).map(p => `  - #${p.number}: ${p.title}`).join('\n');

const langInstruction = lang === 'FR' 
  ? 'Rédige le résumé en français.' 
  : 'Write the summary in English.';

const prompt = `You are a technical writer. Write a weekly narrative summary of GitHub activity for ${repo} covering ${period}.

## Stats
- Commits: ${totalCommits}
- Issues closed: ${totalIssues}
- PRs merged: ${totalPRs}
- Active contributors: ${contributors.slice(0,10).join(', ') || 'N/A'}

## Closed Issues
${issueTitles || '  (none)'}

## Merged PRs
${prTitles || '  (none)'}

${langInstruction}

Format as a friendly narrative (3-4 paragraphs). Highlight key changes, notable fixes, and community contributions.`;

return [{ json: { ...$json, prompt: prompt, stats: { commits: totalCommits, issues: totalIssues, prs: totalPRs, contributors: contributors.slice(0,10) } } }];

